    10	exr_result_t
    11	internal_coding_fill_channel_info (
    12	    exr_coding_channel_info_t**         channels,
    13	    int16_t*                            num_chans,
    14	    exr_coding_channel_info_t*          builtinextras,
    15	    const exr_chunk_info_t*             cinfo,
    16	    const struct _internal_exr_context* pctxt,
    17	    const struct _internal_exr_part*    part)
    18	{
    19	    int                        chans;
    20	    exr_attr_chlist_t*         chanlist;
    21	    exr_coding_channel_info_t* chanfill;
    22	
    23	    chanlist = part->channels->chlist;
    24	    chans    = chanlist->num_channels;
    25	    if (chans <= 5) { chanfill = builtinextras; }
    26	    else
    27	    {
    28	        chanfill = pctxt->alloc_fn (
    29	            (size_t) (chans) * sizeof (exr_coding_channel_info_t));
    30	        if (chanfill == NULL)
    31	            return pctxt->standard_error (pctxt, EXR_ERR_OUT_OF_MEMORY);
    32	        memset (
    33	            chanfill, 0, (size_t) (chans) * sizeof (exr_coding_channel_info_t));
    34	    }
    35	
    36	    for (int c = 0; c < chans; ++c)
    37	    {
    38	        const exr_attr_chlist_entry_t* curc = (chanlist->entries + c);
    39	        exr_coding_channel_info_t*     decc = (chanfill + c);
    40	
    41	        decc->channel_name = curc->name.str;
    42	
    43	        if (curc->y_sampling > 1)
    44	        {
    45	            if (cinfo->height == 1)
    46	                decc->height = ((cinfo->start_y % curc->y_sampling) == 0) ? 1
    47	                                                                          : 0;
    48	            else
    49	                decc->height = cinfo->height / curc->y_sampling;
    50	        }
    51	        else
    52	            decc->height = cinfo->height;
    53	
    54	        if (curc->x_sampling > 1)
    55	            decc->width = cinfo->width / curc->x_sampling;
    56	        else
    57	            decc->width = cinfo->width;
    58	
    59	        decc->x_samples         = curc->x_sampling;
    60	        decc->y_samples         = curc->y_sampling;
    61	        decc->p_linear          = curc->p_linear;
    62	        decc->bytes_per_element = (curc->pixel_type == EXR_PIXEL_HALF) ? 2 : 4;
    63	        decc->data_type         = (uint16_t) (curc->pixel_type);
    64	
    65	        /* initialize these so they don't trip us up during decoding
    66	         * when the user also chooses to skip a channel */
    67	        decc->user_bytes_per_element = decc->bytes_per_element;
    68	        decc->user_data_type         = decc->data_type;
    69	        /* but leave the rest as zero for the user to fill in */
    70	    }
    71	
    72	    *channels  = chanfill;
    73	    *num_chans = (int16_t) chans;
    74	
    75	    return EXR_ERR_SUCCESS;
    76	}
