   137	exr_result_t
   138	internal_encode_free_buffer (
   139	    exr_encode_pipeline_t*               encode,
   140	    exr_transcoding_pipeline_buffer_id_t bufid,
   141	    void**                               buf,
   142	    size_t*                              sz)
   143	{
   144	    void*  curbuf = *buf;
   145	    size_t cursz  = *sz;
   146	    if (curbuf)
   147	    {
   148	        if (cursz > 0)
   149	        {
   150	            if (encode->free_fn)
   151	                encode->free_fn (bufid, curbuf);
   152	            else
   153	            {
   154	                EXR_PROMOTE_CONST_CONTEXT_AND_PART_OR_ERROR_NO_LOCK (
   155	                    encode->context, encode->part_index);
   156	
   157	                pctxt->free_fn (curbuf);
   158	            }
   159	        }
   160	        *buf = NULL;
   161	    }
   162	    *sz = 0;
   163	    return EXR_ERR_SUCCESS;
