   167	internal_encode_alloc_buffer (
   168	    exr_encode_pipeline_t*               encode,
   169	    exr_transcoding_pipeline_buffer_id_t bufid,
   170	    void**                               buf,
   171	    size_t*                              cursz,
   172	    size_t                               newsz)
   173	{
   174	    void* curbuf = *buf;
   175	    if (newsz == 0)
   176	    {
   177	        EXR_PROMOTE_CONST_CONTEXT_AND_PART_OR_ERROR_NO_LOCK (
   178	            encode->context, encode->part_index);
