   180	        return pctxt->print_error (
   181	            pctxt,
   182	            EXR_ERR_INVALID_ARGUMENT,
   183	            "Attempt to allocate 0 byte buffer for transcode buffer %d",
   184	            (int) bufid);
   185	    }
   186	
   187	    if (!curbuf || *cursz < newsz)
   188	    {
   189	        internal_encode_free_buffer (encode, bufid, buf, cursz);
   190	
   191	        if (encode->alloc_fn)
   192	            curbuf = encode->alloc_fn (bufid, newsz);
   193	        else
   194	        {
   195	            EXR_PROMOTE_CONST_CONTEXT_AND_PART_OR_ERROR_NO_LOCK (
   196	                encode->context, encode->part_index);
   197	
   198	            curbuf = pctxt->alloc_fn (newsz);
   199	        }
   200	
   201	        if (curbuf == NULL)
   202	        {
   203	            EXR_PROMOTE_CONST_CONTEXT_AND_PART_OR_ERROR_NO_LOCK (
   204	                encode->context, encode->part_index);
   205	
   206	            return pctxt->print_error (
   207	                pctxt,
   208	                EXR_ERR_OUT_OF_MEMORY,
   209	                "Unable to allocate %" PRIu64 " bytes",
   210	                (uint64_t) newsz);
   211	        }
   212	
   213	        *buf   = curbuf;
   214	        *cursz = newsz;
   215	    }
   216	    return EXR_ERR_SUCCESS;
   217	}
